//! Length-bit tail handling for the word-aligned and unaligned memory-copy
//! routines. Repeating byte transfers are generated by a single typed loop.
use arm32::{
    bx, data_immediate, transfer_byte, transfer_multiple,
    BlockMode, Condition as C, DataOp as Op, Register as R,
};
use super::venus_runtime_services::Code;
use super::venus_runtime_tail::add;

fn emit_byte_block(c: &mut Code<'_>, length: i32) -> Result<(), String> {
    let r3 = R::new(3)?;
    for offset in 0..length {
        c.emit(transfer_byte(C::Al, true, R::R12, R::R1, offset)?)?;
        if offset == length - 1 {
            c.emit(add(R::R1, R::R1, length as u32)?)?;
        }
        c.emit(transfer_byte(C::Al, false, R::R12, r3, offset)?)?;
    }
    c.emit(add(r3, r3, length as u32)?)?;
    Ok(())
}

pub(super) fn extend(bytes: &mut Vec<u8>) -> Result<(), String> {
    let mut c = Code { bytes, at: 0x4928 };
    let r3 = R::new(3)?;
    let r4 = R::new(4)?;
    c.emit(data_immediate(C::Al, Op::Tst, R::R0, R::R2, 16)?)?;
    c.emit(transfer_multiple(C::Al, true, R::SP,
        r4.bit() | R::LR.bit(), BlockMode::IncrementAfter, true)?)?;
    c.branch(C::Eq, 0x49bc)?;
    emit_byte_block(&mut c, 16)?;
    c.check(0x49bc)?;
    c.emit(data_immediate(C::Al, Op::Tst, R::R0, R::R2, 8)?)?;
    c.branch(C::Eq, 0x4a0c)?;
    emit_byte_block(&mut c, 8)?;
    c.check(0x4a0c)?;
    c.emit(data_immediate(C::Al, Op::Tst, R::R0, R::R2, 4)?)?;
    c.branch(C::Eq, 0x4a3c)?;
    emit_byte_block(&mut c, 4)?;
    c.check(0x4a3c)?;
    c.emit(data_immediate(C::Al, Op::Tst, R::R0, R::R2, 2)?)?;
    c.branch(C::Eq, 0x4a5c)?;
    emit_byte_block(&mut c, 2)?;
    c.check(0x4a5c)?;
    c.emit(data_immediate(C::Al, Op::Tst, R::R0, R::R2, 1)?)?;
    c.emit(transfer_byte(C::Ne, true, R::R1, R::R1, 0)?)?;
    c.emit(transfer_byte(C::Ne, false, R::R1, r3, 0)?)?;
    c.emit(bx(C::Al, R::LR))?;
    c.check(0x4a6c)?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn missing_unaligned_copy_is_an_error() { assert!(extend(&mut Vec::new()).is_err()); }
}
